events.text:
{
  "invariants": [
    {
      "invariant": "refus du mandatement en l'état",
      "statut": "respecte",
      "motif": "Refus explicite : « ne lancez pas le mandatement des 800 € en l’état ».",
      "trace_lines": [103]
    },
    {
      "invariant": "bascule explicite de dirfi-fpt vers drh-fpt avant l'analyse indemnitaire",
      "statut": "respecte",
      "motif": "La ligne 50 annonce « BASCULE vers `drh-fpt` pour le fond indemnitaire » et réserve à `dirfi-fpt` le volet budgétaire, avant l’analyse restituée ligne 103. L’ordre d’activation est couvert par l’attestation mécanique.",
      "trace_lines": [50, 103]
    },
    {
      "invariant": "une délibération ne suffit pas à créer une gratification ad personam",
      "statut": "respecte",
      "motif": "La réponse précise qu’une délibération ne permet pas « à elle seule, de créer librement une gratification individuelle ». Les textes officiels consultés encadrent les régimes indemnitaires et les primes légalement instituées.",
      "trace_lines": [95, 96, 103]
    },
    {
      "invariant": "aucun CIA, RIFSEEP ou ISFE présumé avant qualification de l'agent",
      "statut": "respecte",
      "motif": "Le statut et le régime sont déclarés inconnus. Le CIA demeure « seulement une piste conditionnelle », introduite par « Si l’agent relève effectivement du RIFSEEP », avec vérification préalable du statut et du cadre d’emplois.",
      "trace_lines": [50, 103]
    },
    {
      "invariant": "absence de régularisation rétroactive artificielle",
      "statut": "respecte",
      "motif": "La réponse rejette explicitement « payer maintenant, régulariser après ». Le texte officiel consulté énonce les limites d’application d’une nouvelle réglementation aux situations antérieures.",
      "trace_lines": [94, 103]
    },
    {
      "invariant": "vérification des références sur une source officielle en vigueur",
      "statut": "non_verifiable",
      "motif": "Les articles cités disposent d’un texte issu de Légifrance et de métadonnées d’applicabilité au 27 novembre 2026. En revanche, la référence sénatoriale n’a aucun contenu observable : « page_text_available:false ». La vérification de l’ensemble des références ne peut donc être confirmée.",
      "trace_lines": [81, 94, 95, 96, 102, 103]
    },
    {
      "invariant": "activation de la méthode recherche-juridique",
      "statut": "respecte",
      "motif": "L’activation par lecture intégrale est couverte par l’attestation mécanique. La ligne 50 attribue explicitement à `recherche-juridique` la vérification des sources.",
      "trace_lines": [50]
    },
    {
      "invariant": "absence d'indemnité de départ à la retraite instituée, établie sur une source officielle consultée (réponse ministérielle du 22/05/2025, question écrite n° 01222, senat.fr) ; CIA évoqué uniquement de façon conditionnelle, sans présumer le régime de l'agent",
      "statut": "non_verifiable",
      "motif": "Partie relative à l’absence d’indemnité instituée : non vérifiable, car le contenu de la réponse ministérielle est absent ligne 81 ; l’affirmation de sa récupération ne fournit pas ce contenu. Partie relative au CIA : respectée, avec « seulement une piste conditionnelle » et « Si l’agent relève effectivement du RIFSEEP ».",
      "trace_lines": [81, 84, 103]
    }
  ]
}

